INSERT INTO `sp_goods` VALUES ('767', '日康吉米婴儿浴盆RK-3626', '0.00', '100', '100', '774', '<div class=\"lazyimg\"><p><a title=\"1226母婴日\" href=\"https://cuxiao.suning.com/1226muyingri.html\" target=\"_blank\"><img data-src=\"https://image.suning.cn/uimg/sop/commodity/229506581117694398920900_x.jpg?from=mobile&amp;format=80q.webp\" alt=\"\" src=\"https://image.suning.cn/uimg/sop/commodity/229506581117694398920900_x.jpg?from=mobile&format=80q.webp\" width=\"100%\" height=\"auto\"></a></p><div moduleid=\"R9000431_3\" modulename=\"商品详情\"><p> </p>\n<!-- 母婴用品互联3.10 -->\n<p><span><strong>品牌介绍</strong>：日康以“安全、易用、时尚”的品牌理念，依照消费者需求，在产品设计制造的各个环节精益求精。我们崇尚道德营销，并积极推动社会公益事业，提倡简单、健康 的生活价值观念，引导积极、有爱的生活态度，传播育婴的幸福感，倾力构建和谐、快乐的生活氛围。 日康——倡导简爱时尚育儿生活的体验！</span></p>\n<p><img data-src=\"//image.suning.cn/uimg/sop/commodity/137832665898487614865020_x.jpg?from=mobile&amp;format=80q.webp\" alt=\"\" src=\"//image.suning.cn/uimg/sop/commodity/137832665898487614865020_x.jpg?from=mobile&format=80q.webp\" width=\"100%\" height=\"auto\"></p>\n<p> <img data-src=\"//image.suning.cn/uimg/sop/commodity/139210151254832953674340_x.jpg?from=mobile&amp;format=80q.webp\" alt=\"\" src=\"//image.suning.cn/uimg/sop/commodity/139210151254832953674340_x.jpg?from=mobile&format=80q.webp\" width=\"100%\" height=\"auto\"><img data-src=\"//image.suning.cn/uimg/sop/commodity/141578137513163773533631_x.jpg?from=mobile&amp;format=80q.webp\" alt=\"\" src=\"//image.suning.cn/uimg/sop/commodity/141578137513163773533631_x.jpg?from=mobile&format=80q.webp\" width=\"100%\" height=\"auto\"></p></div><div moduleid=\"R9000431_4\" modulename=\"商品参数\"><p><img data-src=\"//image.suning.cn/uimg/sop/commodity/135767571313308442849479_x.jpg?from=mobile&amp;format=80q.webp\" alt=\"\" src=\"//image.suning.cn/uimg/sop/commodity/135767571313308442849479_x.jpg?from=mobile&format=80q.webp\" width=\"100%\" height=\"auto\"></p></div><div moduleid=\"R9000431_5\" modulename=\"商品实拍\"><p><img data-src=\"//image.suning.cn/uimg/sop/commodity/11067082541627