INSERT INTO `sp_goods` VALUES ('811', '【苏宁红孩子】纽曼思(Nemans) DHA藻油软胶囊0.44克/粒×90粒（儿童）美国原装进口', '499.00', '100', '100', '829', '<div class=\"lazyimg\"><p><a title=\"1226母婴日\" href=\"https://cuxiao.suning.com/1226muyingri.html\" target=\"_blank\"><img data-src=\"https://image.suning.cn/uimg/sop/commodity/229506581117694398920900_x.jpg?from=mobile&amp;format=80q.webp\" alt=\"\" src=\"https://image.suning.cn/uimg/sop/commodity/229506581117694398920900_x.jpg?from=mobile&format=80q.webp\" width=\"100%\" height=\"auto\"></a></p><div moduleid=\"R9000511_4\" modulename=\"商品参数\"><p><img data-src=\"//image.suning.cn/uimg/sop/commodity/135609032044022686627210_x.jpg?from=mobile&amp;format=80q.webp\" alt=\"\" src=\"//image.suning.cn/uimg/sop/commodity/135609032044022686627210_x.jpg?from=mobile&format=80q.webp\" width=\"100%\" height=\"auto\"></p><p>[品        名]       纽曼思（原名纽曼斯）DHA海藻软胶囊 婴幼儿90粒装</p><p>[适用人群]      0-6周岁婴幼儿</p><p>[食用方法]      每日1-2粒刺破胶囊直接滴入宝宝口中或滴入辅食中随餐服用</p><p>[产品规格]      260mg/粒（90粒/瓶）每粒DHA含量100mg</p><p>[保  质  期]      36个月</p><p>[温馨提示]      存放在阴凉干燥（25度以下，湿度75%以下）、儿童不易接触的地方。开封后请旋紧瓶盖并存放于冰箱冷藏中保存。</p><p>                        产品如果长期存放或遇到温度变化会观察到胶囊内出现半固体状的沉淀，这种现象并不影响产品的质量和食用。</p><p> </p><p> </p></div><div moduleid=\"R9000511_5\" modulename=\"商品展示\"><p><img data-src=\"//image.suning.cn/uimg/sop/commodity/630691966373271030209500_x.jpg?from=mobile&amp;format=80q.webp\" alt=\"\" src=\"//image.suning.cn/uimg/sop/commodity/630691966373271030209500_x.jpg?from=mobile&format=80q.webp\" width=\"100%\" height=\"auto\"></p></div><div moduleid=\"R9000511_3\" modulename=\"商品详情\"><p> </p><p> </p></div></div>', '', '', '0', '1514258951', '1514258951', null, '710', '818', '829', '0', '0', '0');
